import {expandCareContent} from './content-sections.js';
export {careComparison,aboutExtra,contactExtra,journalExtra,privacyExtra} from './content-sections.js';
import {services,conditions,medications,professionalPages,helpTopics} from './care-data.js';
export {services,conditions,medications,professionalPages,helpTopics};
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(path,name,cls='')=>`<a class="${cls}" href="${esc(path)}">${esc(name)} <span aria-hidden="true">↗</span></a>`;
const options=(items,value)=>items.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
const box=(heading,text)=>`<div><h3>${esc(heading)}</h3><p>${esc(text)}</p></div>`;
export const routePaths=[...new Set(['/services','/psychiatry','/psychiatry/medications','/treatment','/resources','/mental-health/conditions','/assessments','/help','/therapists','/get-started','/coverage','/coverage/insurance/tricare','/coverage/insurance/medicare','/nyc-teenspace',...services.map(x=>x.path),...conditions.map(x=>x.path),...medications.map(x=>x.path),...professionalPages.map(x=>x.path)])];
export function navigation(){return [['Therapy',services,'/services'],['Psychiatry & medication',[{name:'Psychiatry',path:'/psychiatry'},...medications],'/psychiatry/medications'],['Treatments',conditions,'/treatment'],['Resources',[{name:'The journal',path:'/blog'},{name:'Mental health conditions',path:'/mental-health/conditions'},{name:'Free mental health tests',path:'/assessments'},{name:'Help center',path:'/help'},{name:'Therapists near me',path:'/therapists'},...professionalPages],'/resources']].map(([name,items,all])=>`<details class="mega" name="main-navigation"><summary><span>${name}</span><svg class="nav-chevron" width="14" height="14" viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false"><path d="m5 7.5 5 5 5-5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg></summary><div class="mega-panel"><p class="eyebrow">Explore ${name.toLowerCase()}</p><div class="mega-grid">${items.map(x=>link(x.path,x.name)).join('')}</div>${link(all,'Explore all','text-link')}</div></details>`).join('');}
export function footerLinks(){return [['Care in India',services.slice(0,2).concat([{path:'/online-therapy/teens',name:'Teen therapy'},{path:'/psychiatry',name:'Psychiatry'},{path:'/therapists',name:'Find a therapist'}])],['Explore',[{path:'/treatment',name:'Treatments'},{path:'/resources',name:'Mental health resources'},{path:'/assessments',name:'Free mental health tests'},{path:'/help',name:'Help center'},{path:'/coverage',name:'Fees & coverage'}]],['For professionals',professionalPages]].map(([title,items])=>`<div class="footer-col"><strong>${title}</strong>${items.map(x=>link(x.path,x.name)).join('')}</div>`).join('');}
function hero(label,title,description,image='/assets/talk.jpg'){return `<section class="wrap care-hero"><div><a class="crumb" href="/services">Care in India</a><p class="eyebrow">${esc(label)}</p><h1>${esc(title)}</h1><p class="lead">${esc(description)}</p>${link('/get-started','Explore your next step','btn')}</div><img src="${image}" alt="A quiet space for reflection" width="700" height="680" fetchpriority="high"></section>`;}
function heading(label,title,description){return `<section class="wrap page-top"><p class="eyebrow">${esc(label)}</p><h1>${esc(title)}</h1><p>${esc(description)}</p></section>`;}
function catalog(items){return `<section class="wrap section care-catalog"><label class="catalog-search">Find a topic<input type="search" data-catalog-search placeholder="Search by name" aria-label="Search topics"></label><div class="care-link-grid">${items.map(x=>`<a class="care-link" data-catalog-item="${esc((x.name+' '+(x.description||'')).toLowerCase())}" href="${x.path}"><h3>${esc(x.name)}</h3>${x.description?`<p>${esc(x.description)}</p>`:''}<span aria-hidden="true">↗</span></a>`).join('')}</div><p data-catalog-empty hidden role="status">No matching topics. Try another word.</p></section>`;}
function faq(items){return `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`;}
function end(){return `<section class="wrap section"><div class="care-band"><div><p class="eyebrow">A place to begin</p><h2>Find support that fits your life.</h2><p>Explore a provider, a service, or simply a question.</p></div>${link('/get-started','Start an enquiry','btn')}</div></section>`;}
export function homeCare(){return `<section class="wrap section"><div class="section-head"><div><p class="eyebrow">Therapy, for real life</p><h2>Space for every part of you.</h2></div>${link('/services','All care options','text-link')}</div><div class="care-feature-grid">${[services[0],services[1],services[8]].map(s=>`<a class="care-feature" href="${s.path}"><img src="${s.image}" alt="" loading="lazy" width="500" height="400"><p class="eyebrow">${s.name}</p><h3>${s.heading}</h3><p>${s.description}</p><span class="text-link">Explore care ↗</span></a>`).join('')}</div></section><section class="wrap"><div class="care-band"><div><p class="eyebrow">Psychiatry</p><h2>A clearer picture.<br>A considered care plan.</h2><p>Explore psychiatric assessment and medication management in India.</p></div>${link('/psychiatry','Explore psychiatry','btn')}</div></section><section class="wrap section"><div class="section-head"><h2>Make sense of what<br>you’re going through.</h2>${link('/treatment','All treatment topics','text-link')}</div><div class="topic-chips">${conditions.slice(0,6).map(c=>link(c.path,c.name)).join('')}</div></section>`;}
export function directoryResults(providers,filters={}){const matches=providers.filter(p=>p.active&&p.verified&&['city','profession'].every(k=>!filters[k]||String(p[k]).toLowerCase().includes(filters[k].toLowerCase()))&&(!filters.language||p.languages.some(l=>l.toLowerCase().includes(filters.language.toLowerCase())))&&(!filters.concern||p.specialties.some(l=>l.toLowerCase().includes(filters.concern.toLowerCase()))));return matches.length?`<p role="status">${matches.length} provider${matches.length===1?'':'s'} found</p><div class="provider-grid">${matches.map(p=>`<article class="provider-card"><span class="provider-avatar" aria-hidden="true">${esc(p.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><p class="eyebrow">${esc(p.profession)}</p><h2>${esc(p.name)}</h2><p>${esc(p.credentials)}</p><p>${esc(p.city)} · ${esc(p.languages.join(', '))}</p><p>${esc(p.specialties.join(' · '))}</p>${link('/therapists/'+p.slug,'Meet '+p.name,'text-link')}</article>`).join('')}</div>`:`<div class="empty"><h2>${providers.some(p=>p.active&&p.verified)?'No matching providers.':'Our directory is being prepared.'}</h2><p>${providers.some(p=>p.active&&p.verified)?'Try fewer filters or ask about your preferences.':'Profiles will appear after the Stillwell team adds and verifies its clinicians.'}</p>${link('/get-started','Ask about care','btn')}</div>`;}
export function requestForm(params=new URLSearchParams(),kind='consultation',providers=[]){const selected=params.get('service')||'Help me choose';const provider=providers.find(p=>p.id===params.get('provider')&&p.active&&p.verified);return `<form id="care-request-form" class="form care-request" data-kind="${kind}"><div class="notice"><strong>Testing mode</strong><br>This enquiry is saved privately for the administrator to review. No email is sent and no appointment is booked. Please use test details and do not include health information.</div>${provider?`<p>Preferred provider: <strong>${esc(provider.name)}</strong></p>`:''}<input type="hidden" name="provider_id" value="${esc(provider?.id||'')}"><label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="step-progress" role="status">Step 1 of 3 · Your preferences</p><fieldset data-form-step="0"><legend>Your preferences</legend><label>What are you looking for?<select name="service">${options(['Help me choose',...services.map(s=>s.name),'Psychiatry',...(kind!=='consultation'?['Professional enquiry']:[])],kind==='consultation'?selected:'Professional enquiry')}</select></label><div class="pair"><label>City in India<input name="city" required minlength="2" maxlength="100" autocomplete="address-level2"></label><label>Preferred language<input name="language" required minlength="2" maxlength="50" value="English"></label></div><label>Session preference<select name="mode">${options(['Online','In person','Either'],'Online')}</select></label><label>I am enquiring as<select name="relationship">${options(['Adult seeking care','Parent or legal guardian','Professional enquiry'],kind==='consultation'?(selected==='Teen therapy'?'Parent or legal guardian':'Adult seeking care'):'Professional enquiry')}</select></label><p class="small">For teen therapy, a parent or legal guardian must start the enquiry. No child’s name or health details are needed.</p><button type="button" class="btn" data-request-next>Continue →</button></fieldset><fieldset data-form-step="1" hidden disabled><legend>Your contact details</legend><label>Your name<input name="contact_name" required minlength="2" maxlength="100" autocomplete="name"></label><label>Email<input name="email" required type="email" maxlength="180" autocomplete="email"></label><label>Phone (optional)<input name="phone" type="tel" maxlength="30" autocomplete="tel"></label>${kind!=='consultation'?'<label>Your professional background<textarea name="professional_details" maxlength="1000" placeholder="Your own qualifications, registration or organisation. No patient details or medical records."></textarea></label>':''}<div class="form-actions"><button type="button" class="btn light" data-request-back>← Back</button><button type="button" class="btn" data-request-next>Review enquiry →</button></div></fieldset><fieldset data-form-step="2" hidden disabled><legend>Review your test enquiry</legend><div id="request-review"></div><label class="check-label"><input name="consent" type="checkbox" required> I agree to these test contact details being stored for the administrator to review. This is not a booking or a request for urgent care.</label><p class="small">Read our <a href="/privacy">privacy information</a>. For immediate danger or a medical emergency, contact local emergency services or the nearest emergency department.</p><div class="form-actions"><button type="button" class="btn light" data-request-back>← Back</button><button class="btn" type="submit">Submit test enquiry ↗</button></div></fieldset><p class="form-error" role="alert" id="request-error"></p></form>`;}
export function requestStep(form,direction){const current=Number(form.dataset.step||0);const fields=form.querySelector(`[data-form-step="${current}"]`);if(direction>0){for(const el of fields.querySelectorAll('input,select,textarea'))if(!el.reportValidity())return;if(form.elements.service.value==='Teen therapy'&&form.elements.relationship.value!=='Parent or legal guardian'){form.querySelector('#request-error').textContent='For teen therapy, choose Parent or legal guardian.';return;}}const next=Math.max(0,Math.min(2,current+direction));form.dataset.step=next;form.querySelectorAll('[data-form-step]').forEach((f,i)=>{f.hidden=i!==next;f.disabled=i!==next;});form.querySelector('#request-error').textContent='';form.querySelector('.step-progress').textContent=`Step ${next+1} of 3 · ${['Your preferences','Your contact details','Review'][next]}`;if(next===2)form.querySelector('#request-review').innerHTML=`<dl class="review-list">${[['Service','service'],['Location','city'],['Language','language'],['Format','mode'],['Enquiring as','relationship'],['Name','contact_name'],['Email','email'],['Phone','phone'],...(form.elements.professional_details?[['Professional background','professional_details']]:[])].map(([l,n])=>`<dt>${l}</dt><dd>${esc(form.elements[n].value)}</dd>`).join('')}</dl>`;form.querySelector(`[data-form-step="${next}"] legend`).setAttribute('tabindex','-1');form.querySelector(`[data-form-step="${next}"] legend`).focus();}
export function renderCare(path,params=new URLSearchParams(),providers=[]){let title,description,html;const s=services.find(x=>x.path===path),c=conditions.find(x=>x.path===path),m=medications.find(x=>x.path===path),professional=professionalPages.find(x=>x.path===path);
 if(s){title=s.name;description=s.description;html=hero(s.name,s.heading,s.description,s.image)+`<section class="wrap section care-editorial"><div><p class="eyebrow">Room to explore</p><h2>A conversation shaped around you.</h2><div class="topic-chips">${s.topics.map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><div><h3>What to expect</h3><p>${esc(s.expect)}</p>${link('/get-started?service='+encodeURIComponent(s.name),'Enquire about '+s.name.toLowerCase(),'text-link')}</div></section>`+end();}
 else if(c){title=c.name;description=c.description;html=hero('Understanding '+c.name,c.heading,c.description,'/assets/slow.jpg')+`<section class="wrap section care-editorial"><div><h2>Questions for a first conversation.</h2><p>You do not need to have all the answers. A qualified clinician can help you understand what is happening and what support may fit.</p></div><div>${c.questions.map((q,i)=>box('0'+(i+1),q)).join('')}</div></section><section class="wrap medical-note"><p>General educational information, not a diagnosis or an individual treatment plan.</p>${link(c.source,'Read the clinical information source','text-link')}</section>`+end();}
 else if(m){title=m.name+(m.brand?' ('+m.brand+')':'');description=`Learn about ${m.name}, questions to discuss with a psychiatrist, and where to find medicine information.`;html=heading('Medication information',title,description)+`<section class="wrap section care-editorial"><div><p class="eyebrow">${esc(m.group)}</p><h2>Understand your prescription.</h2><p>A psychiatrist considers your symptoms, history, other medicines, and preferences before discussing whether a medication is appropriate.</p><p>Brand names, licensed uses, and availability vary by country. A brand listed here does not imply availability in India.</p>${link(m.source,'Read the MedlinePlus medicine guide','text-link')}</div><div><h3>Discuss with your prescriber</h3><ul class="care-points"><li>Why this medicine is being considered for you.</li><li>Possible benefits, side effects, interactions, and monitoring.</li><li>What to do if you miss a dose or have a concern.</li><li>Pregnancy, other health conditions, and all medicines or supplements you take.</li></ul><p class="notice">This website does not prescribe or sell medicines. Do not start, stop, or change medication using this page. Ask your prescriber or pharmacist for personal guidance.</p>${link('/get-started?service=Psychiatry','Ask about psychiatry','btn')}</div></section>`;}
 else if(professional){title=professional.name;description=professional.description;html=heading('For professionals',professional.heading,description)+`<section class="wrap contact-grid section">${requestForm(params,professional.kind,providers)}<aside><h2>Care starts with connection.</h2><p>All professional enquiries are reviewed by the Stillwell administrator. Submitting this test form does not establish employment, a partnership, or a patient referral.</p>${link('/help','Visit the help center','text-link')}</aside></section>`;}
 else if(path==='/services'){title='Therapy in India';description='Explore individual, couples, teen and specialist therapy services in India.';html=hero('Care in India','Different lives. Room for all of them.',description)+catalog(services)+end();}
 else if(path==='/psychiatry'){title='Psychiatry and medication management';description='Explore psychiatric assessment and a considered approach to medication management in India.';html=hero('Psychiatry','A clearer understanding. A plan for you.',description,'/assets/journal.jpg')+`<section class="wrap section"><div class="values">${box('Begin with an assessment','Discuss your experiences, health history, current medicines, and goals with a qualified psychiatrist.')}${box('Make informed decisions','Ask about treatment options, potential benefits and risks, and what follow-up involves.')}${box('Keep care connected','Therapy, medical care, and practical support may work together. The clinician will discuss what is suitable.')}</div></section>`+catalog(medications)+end();}
 else if(path==='/psychiatry/medications'){title='Medication information';description='Explore medicine information and questions to discuss with a qualified prescriber. No online prescribing or medicine sales.';html=heading('Learn before your appointment',title,description)+catalog(medications);}
 else if(['/treatment','/mental-health/conditions'].includes(path)){title='Mental health conditions and treatments';description='Understand common mental health concerns and prepare for a conversation with a qualified clinician.';html=heading('Understanding your experience','A little clarity can be a beginning.',description)+catalog(conditions)+end();}
 else if(path==='/resources'){title='Mental health resources';description='A place for reading, reflection, practical questions, and finding support.';html=heading('Learn at your own pace','Make room for a new perspective.',description)+catalog([{name:'The journal',path:'/blog',description:'Stories and ideas for everyday wellbeing.'},{name:'Mental health conditions',path:'/mental-health/conditions',description:'Understand concerns and prepare for a conversation.'},{name:'Free mental health tests',path:'/assessments',description:'Explore external screening tools and a private reflection.'},{name:'Help center',path:'/help',description:'Answers about starting care, formats, and privacy.'},{name:'Health collective',path:'/partners/health-collective',description:'Connect with Stillwell as a professional or organisation.'},{name:'Fees & coverage',path:'/coverage',description:'Questions to ask before you book.'},{name:'NYC Teenspace',path:'/nyc-teenspace',description:'Information about a separate US program.'}]);}
 else if(path==='/help'){title='Help center';description='Clear answers about getting started with Stillwell in India.';html=heading('A little clarity',title,description)+`<section class="wrap section help-content">${faq(helpTopics)}</section>`+end();}
 else if(path==='/assessments'){title='Free mental health tests and reflection';description='Explore external screening resources and think about the support you would like.';html=heading('A moment to check in','Start with how life feels.',description)+`<section class="wrap section care-editorial"><div><h2>Free screening resources</h2><p>Mental Health America offers external screening tools for concerns such as anxiety and depression. These tools do not diagnose a condition and are not a substitute for a professional assessment.</p><p>The service is US-based; its privacy terms and support pathways apply when you leave Stillwell.</p>${link('https://screening.mhanational.org/screening-tools/','Explore free screening tools','btn')}</div><form class="form" id="reflection-form"><h2>A private reflection</h2><p>This is a conversation starter, not a clinical test. Your choices are not saved or sent.</p><label>What would you like support with?<select name="focus">${options(['Everyday stress','Relationships','Life changes','Understanding my mood','I am not sure yet'])}</select></label><label>What might be useful next?<select name="next">${options(['Read about therapy','Explore providers','Ask about psychiatry','Read the journal'])}</select></label><button class="btn" type="submit">Explore a next step ↗</button><div id="reflection-result" aria-live="polite"></div></form></section>`;}
 else if(path==='/therapists'){title='Find a therapist in India';description='Browse verified provider profiles and filter by city, language, profession, or concern.';html=heading('Find a connection','The right fit starts with you.',description)+`<section class="wrap section"><form id="directory-form" class="directory-filters form"><label>City<input name="city" placeholder="e.g. Bengaluru"></label><label>Language<input name="language" placeholder="e.g. Hindi"></label><label>Profession<select name="profession"><option value="">All professions</option>${options(['Therapist','Clinical psychologist','Psychiatrist','Counsellor'])}</select></label><label>Concern<input name="concern" placeholder="e.g. Relationships"></label><button class="btn" type="submit">Find providers</button><button class="btn light" type="reset">Reset</button></form><div id="directory-results">${directoryResults(providers)}</div></section>`;}
 else if(path.startsWith('/therapists/')){const p=providers.find(p=>p.active&&p.verified&&'/therapists/'+p.slug===path);if(!p)return null;title=p.name;description=p.bio.slice(0,160);html=heading(p.profession,p.name,p.credentials)+`<section class="wrap section care-editorial"><div><h2>Meet ${esc(p.name)}</h2><p class="preserve-lines">${esc(p.bio)}</p><p>${esc(p.registration?'Registration: '+p.registration:'')}</p></div><div><h3>Practice details</h3><p>${esc(p.city)} · ${esc(p.modes.join(' / '))}</p><p>Languages: ${esc(p.languages.join(', '))}</p><p>Areas of focus: ${esc(p.specialties.join(', '))}</p>${link('/get-started?provider='+p.id+'&service='+encodeURIComponent(p.profession==='Psychiatrist'?'Psychiatry':'Individual therapy'),'Enquire about availability','btn')}<p class="small">Fees and appointment availability are confirmed separately.</p></div></section>`;}
 else if(path==='/get-started'){title='Start a care enquiry';description='Tell us your care preferences in India. Test enquiries only; no appointment is booked.';html=heading('One small step','Let’s find your starting point.',description)+`<section class="wrap contact-grid section">${requestForm(params,'consultation',providers)}<aside><p class="eyebrow">At your pace</p><h2>You don’t need the perfect words.</h2><p>Choose a service, location, and format. You can discuss personal health details with your clinician through an agreed care process.</p>${link('/therapists','Explore the directory','text-link')}<div class="mini-faq">${faq(helpTopics.slice(1,4))}</div></aside></section>`;}
 else if(path==='/coverage'){title='Fees and coverage in India';description='Know what to ask about fees, payment, cancellations, and insurance before starting care.';html=heading('Practical details','Clarity before you commit.',description)+`<section class="wrap section"><div class="values">${box('Understand the full fee','Ask about session length, consultation and follow-up fees, taxes, and cancellation terms. Fees have not yet been published on this website.')}${box('Confirm any reimbursement','Check your own policy and ask your insurer about outpatient mental health cover, documents, and provider eligibility. Stillwell does not guarantee reimbursement.')}</div><h2>About US programs in the reference</h2><p>Medicare, TRICARE, and NYC Teenspace are separate US programs. They are not offered as Stillwell India coverage.</p><div class="topic-chips">${link('/coverage/insurance/medicare','Medicare information')}${link('/coverage/insurance/tricare','TRICARE information')}${link('/nyc-teenspace','NYC Teenspace information')}</div></section>`;}
 else if(['/coverage/insurance/medicare','/coverage/insurance/tricare','/nyc-teenspace'].includes(path)){title=path.includes('medicare')?'Medicare':path.includes('tricare')?'TRICARE':'NYC Teenspace';description=`${title} is a separate US program, not Stillwell India coverage or a Stillwell-operated service.`;const dest=path.includes('medicare')?services[6]:path.includes('tricare')?services[4]:services[8];html=heading('External US program',title,description)+`<section class="wrap section"><p>Stillwell serves India. Explore our relevant care information and confirm local availability with the care team.</p>${link(dest.path,dest.name,'btn')}${path==='/nyc-teenspace'?`<p>${link('https://www.nycteenspace.com/','Visit the separate NYC Teenspace website','text-link')}</p>`:''}</section>`;}
 else return null;
 html=expandCareContent(path,html);return {html,title,description};
}
export function handleInput(target){if(!target.matches('[data-catalog-search]'))return;let count=0;target.closest('.care-catalog').querySelectorAll('[data-catalog-item]').forEach(el=>{el.hidden=!el.dataset.catalogItem.includes(target.value.toLowerCase().trim());if(!el.hidden)count++;});target.closest('.care-catalog').querySelector('[data-catalog-empty]').hidden=count>0;}
export function reflect(form){const paths={'Read about therapy':'/services','Explore providers':'/therapists','Ask about psychiatry':'/psychiatry','Read the journal':'/blog'};form.querySelector('#reflection-result').innerHTML=`<div class="notice"><h3>A starting point for you</h3><p>You chose ${esc(form.elements.focus.value.toLowerCase())}. You can explore support without deciding everything today.</p>${link(paths[form.elements.next.value],form.elements.next.value,'text-link')}</div>`;}
